CREATE TABLE public.hair_salons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, settings jsonb NOT NULL DEFAULT '{}'::jsonb, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.hair_salons TO anon,authenticated; GRANT UPDATE ON public.hair_salons TO authenticated; GRANT ALL ON public.hair_salons TO service_role;
ALTER TABLE public.hair_salons ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.hair_salon_admins (salon_id uuid NOT NULL REFERENCES public.hair_salons(id), user_id uuid NOT NULL, PRIMARY KEY(salon_id,user_id));
GRANT SELECT ON public.hair_salon_admins TO authenticated; GRANT ALL ON public.hair_salon_admins TO service_role;
ALTER TABLE public.hair_salon_admins ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_membership ON public.hair_salon_admins FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_hair_salon_admin(sid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.hair_salon_admins WHERE salon_id=sid AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_hair_salon_admin(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_hair_salon_admin(uuid) TO authenticated;
CREATE POLICY public_active_salons ON public.hair_salons FOR SELECT TO anon,authenticated USING(active);
CREATE POLICY salon_admin_read ON public.hair_salons FOR SELECT TO authenticated USING(public.is_hair_salon_admin(id));
CREATE POLICY salon_admin_edit ON public.hair_salons FOR UPDATE TO authenticated USING(public.is_hair_salon_admin(id)) WITH CHECK(public.is_hair_salon_admin(id));
CREATE TABLE public.hair_salon_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.hair_salons(id), name text NOT NULL, brand text NOT NULL, function text NOT NULL, concerns text[] NOT NULL DEFAULT '{}', description text NOT NULL DEFAULT '', purchase_url text NOT NULL DEFAULT '', price text NOT NULL DEFAULT '', verified boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.hair_salon_products TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.hair_salon_products TO authenticated; GRANT ALL ON public.hair_salon_products TO service_role;
ALTER TABLE public.hair_salon_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_public ON public.hair_salon_products FOR SELECT TO anon,authenticated USING(verified AND active AND EXISTS(SELECT 1 FROM public.hair_salons WHERE id=salon_id AND active));
CREATE POLICY catalog_admin ON public.hair_salon_products FOR ALL TO authenticated USING(public.is_hair_salon_admin(salon_id)) WITH CHECK(public.is_hair_salon_admin(salon_id));
CREATE TABLE public.hair_consultations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.hair_salons(id), secret_hash text NOT NULL, answers jsonb NOT NULL, result jsonb NOT NULL, contact_skipped boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days');
GRANT ALL ON public.hair_consultations TO service_role;
ALTER TABLE public.hair_consultations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.hair_salon_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.hair_salons(id), hair_profile_id uuid UNIQUE NOT NULL REFERENCES public.hair_consultations(id) ON DELETE CASCADE, first_name text NOT NULL, email text NOT NULL, phone_number text NOT NULL, consultation_data_sharing_consent boolean NOT NULL DEFAULT true CHECK(consultation_data_sharing_consent), consultation_consent_timestamp timestamptz NOT NULL DEFAULT now(), email_marketing_consent boolean NOT NULL DEFAULT false, email_marketing_consent_timestamp timestamptz, sms_marketing_consent boolean NOT NULL DEFAULT false, sms_marketing_consent_timestamp timestamptz, consent_notice_version text NOT NULL, consent_source text NOT NULL, consent_evidence jsonb NOT NULL, consultation_answers jsonb NOT NULL, lead_status text NOT NULL DEFAULT 'New' CHECK(lead_status IN ('New','Contacted','Consultation Booked','Customer','Closed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.hair_salon_leads TO authenticated; GRANT ALL ON public.hair_salon_leads TO service_role;
ALTER TABLE public.hair_salon_leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY leads_admin ON public.hair_salon_leads FOR ALL TO authenticated USING(public.is_hair_salon_admin(salon_id)) WITH CHECK(public.is_hair_salon_admin(salon_id));
CREATE TABLE public.hair_salon_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.hair_salons(id), session_id uuid NOT NULL, event text NOT NULL CHECK(event IN ('landing_view','onboarding_start','analysis_completed','contact_view','contact_submitted','contact_skipped','product_view','product_click','booking_click')), product_id uuid REFERENCES public.hair_salon_products(id), concern text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(salon_id,session_id,event,product_id));
GRANT SELECT ON public.hair_salon_events TO authenticated; GRANT ALL ON public.hair_salon_events TO service_role;
ALTER TABLE public.hair_salon_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_admin ON public.hair_salon_events FOR SELECT TO authenticated USING(public.is_hair_salon_admin(salon_id));
CREATE INDEX hair_events_session ON public.hair_salon_events(session_id,created_at);
CREATE INDEX hair_leads_salon_date ON public.hair_salon_leads(salon_id,created_at);
CREATE INDEX hair_consultations_salon_date ON public.hair_consultations(salon_id,created_at);
COMMENT ON TABLE public.hair_consultations IS 'Guest access uses a hashed unguessable capability; no photos or consumer skin data stored. Delete removes linked leads.';